CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, email TEXT UNIQUE NOT NULL, name TEXT NOT NULL DEFAULT '', google_sub TEXT UNIQUE, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS codes (id TEXT PRIMARY KEY, email TEXT NOT NULL, digest TEXT NOT NULL, expires_at INTEGER NOT NULL, attempts INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS codes_email ON codes(email);
CREATE TABLE IF NOT EXISTS sessions (digest TEXT PRIMARY KEY, user_id TEXT NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS limits (key TEXT PRIMARY KEY, attempts INTEGER NOT NULL, resets_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sites (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL, slug TEXT UNIQUE NOT NULL, state TEXT NOT NULL, version INTEGER NOT NULL, record TEXT NOT NULL, published_at INTEGER, trial_ends_at INTEGER, stripe_account TEXT UNIQUE, stripe_subscription TEXT UNIQUE, billing TEXT NOT NULL DEFAULT 'not_started');
CREATE INDEX IF NOT EXISTS sites_owner ON sites(owner_id);
CREATE TABLE IF NOT EXISTS published_sites (site_id TEXT PRIMARY KEY, record TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS photos (site_id TEXT NOT NULL, digest TEXT NOT NULL, data BLOB NOT NULL, type TEXT NOT NULL, PRIMARY KEY(site_id,digest));
CREATE TABLE IF NOT EXISTS domains (host TEXT PRIMARY KEY, site_id TEXT NOT NULL, provider_id TEXT UNIQUE, status TEXT NOT NULL DEFAULT 'pending', verification TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS jobs (id TEXT PRIMARY KEY, site_id TEXT NOT NULL, kind TEXT NOT NULL, due_at INTEGER NOT NULL, state TEXT NOT NULL DEFAULT 'pending', attempts INTEGER NOT NULL DEFAULT 0, result TEXT);
CREATE INDEX IF NOT EXISTS jobs_due ON jobs(state, due_at);
CREATE TABLE IF NOT EXISTS stripe_events (id TEXT PRIMARY KEY, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS support (id TEXT PRIMARY KEY, site_id TEXT NOT NULL, kind TEXT NOT NULL, detail TEXT NOT NULL, created_at INTEGER NOT NULL, state TEXT NOT NULL DEFAULT 'open');
CREATE TABLE IF NOT EXISTS milestones (site_id TEXT NOT NULL, kind TEXT NOT NULL, at INTEGER NOT NULL, PRIMARY KEY(site_id,kind));
CREATE TABLE IF NOT EXISTS onboarding_events (site_id TEXT NOT NULL, step INTEGER NOT NULL, duration_ms INTEGER NOT NULL, at INTEGER NOT NULL, PRIMARY KEY(site_id,step));
CREATE TABLE IF NOT EXISTS billing_methods (site_id TEXT PRIMARY KEY, payment_method TEXT NOT NULL, consent_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS platform_settings (key TEXT PRIMARY KEY,value TEXT NOT NULL);
